\set ON_ERROR_STOP on
BEGIN; SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; SET LOCAL ROLE nexa_runtime;
SELECT set_config('app.current_tenant_id','032b470c-157f-347c-b1df-d00e62788fb2',true),set_config('app.current_workspace_id','7353177c-3274-3830-9d2e-6897a70f6b67',true);
DO $$ BEGIN
 IF (SELECT count(*) FROM catalog_management.product) NOT IN (50,102) OR (SELECT count(*) FROM catalog_management.sellable_sku) NOT IN (50,102) OR (SELECT count(*) FROM catalog_management.product_asset_reference) NOT IN (50,102) THEN RAISE EXCEPTION 'Unexpected catalog baseline'; END IF;
 IF (SELECT count(*) FROM catalog_management.sku_price)<>50 OR (SELECT count(*) FROM catalog_management.product_price)<>50 THEN RAISE EXCEPTION 'Protected price baseline changed'; END IF;
END $$;
