INSERT INTO catalog_management.brand(id,tenant_id,workspace_id,slug,name,status,version,created_at,updated_at) SELECT id,'032b470c-157f-347c-b1df-d00e62788fb2','7353177c-3274-3830-9d2e-6897a70f6b67',slug,name,'ACTIVE',0,now(),now() FROM import_brand ON CONFLICT(tenant_id,workspace_id,slug) DO NOTHING;
