DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM import_product n JOIN catalog_management.product p ON p.tenant_id='032b470c-157f-347c-b1df-d00e62788fb2' AND p.workspace_id='7353177c-3274-3830-9d2e-6897a70f6b67' AND p.catalog_item_id=n.catalog_item_id WHERE p.id<>n.product_id OR p.product_code<>n.product_code OR p.name<>n.name OR p.description<>n.description OR p.category_id<>n.category_id OR p.brand_id<>n.brand_id OR p.storage_temperature<>n.storage) THEN RAISE EXCEPTION 'Existing provisional product differs'; END IF;
 IF EXISTS(SELECT 1 FROM import_product n JOIN catalog_management.sellable_sku s ON s.tenant_id='032b470c-157f-347c-b1df-d00e62788fb2' AND s.workspace_id='7353177c-3274-3830-9d2e-6897a70f6b67' AND s.legacy_catalog_item_id=n.catalog_item_id WHERE s.sku_code<>n.sku_code OR s.gtin IS NOT NULL OR s.net_weight IS NOT NULL OR s.gross_weight IS NOT NULL) THEN RAISE EXCEPTION 'Existing provisional SKU differs'; END IF;
END $$;
INSERT INTO catalog_management.product(id,tenant_id,workspace_id,catalog_item_id,product_code,slug,name,description,category_id,brand_id,storage_temperature,status,version,created_at,updated_at) SELECT product_id,'032b470c-157f-347c-b1df-d00e62788fb2','7353177c-3274-3830-9d2e-6897a70f6b67',catalog_item_id,product_code,slug,name,description,category_id,brand_id,storage,'ACTIVE',0,now(),now() FROM import_product ON CONFLICT(tenant_id,workspace_id,catalog_item_id) DO NOTHING;
INSERT INTO catalog_management.product_presentation(product_id,tenant_id,workspace_id,presentation,unit_of_measure,version,updated_at) SELECT product_id,'032b470c-157f-347c-b1df-d00e62788fb2','7353177c-3274-3830-9d2e-6897a70f6b67',presentation,'UNIT',0,now() FROM import_product ON CONFLICT(product_id) DO NOTHING;
INSERT INTO catalog_management.product_visibility(product_id,tenant_id,workspace_id,buyer_visible,sales_visible,warehouse_visible,logistics_visible,version,updated_at) SELECT product_id,'032b470c-157f-347c-b1df-d00e62788fb2','7353177c-3274-3830-9d2e-6897a70f6b67',false,true,true,true,0,now() FROM import_product ON CONFLICT(product_id) DO NOTHING;
INSERT INTO catalog_management.product_asset_reference(id,tenant_id,workspace_id,product_id,asset_path,file_name,alt_text,sort_order) SELECT asset_id,'032b470c-157f-347c-b1df-d00e62788fb2','7353177c-3274-3830-9d2e-6897a70f6b67',product_id,asset_path,file_name,name,0 FROM import_product ON CONFLICT(tenant_id,workspace_id,product_id,asset_path) DO NOTHING;
INSERT INTO catalog_management.product_family(id,tenant_id,workspace_id,family_code,name,description,category_id,brand_id,storage_family,status,version,created_at,updated_at) SELECT family_id,'032b470c-157f-347c-b1df-d00e62788fb2','7353177c-3274-3830-9d2e-6897a70f6b67',family_code,family_name,description,category_id,brand_id,storage,'ACTIVE',0,now(),now() FROM import_product ON CONFLICT(tenant_id,workspace_id,family_code) DO NOTHING;
INSERT INTO catalog_management.sellable_sku(id,tenant_id,workspace_id,family_id,legacy_product_id,legacy_catalog_item_id,sku_code,presentation,packaging_type,unit_of_measure,pack_quantity,minimum_remaining_shelf_life_days,lot_tracking_required,expiry_tracking_required,tax_category,status,visible,version,created_at,updated_at) SELECT product_id,'032b470c-157f-347c-b1df-d00e62788fb2','7353177c-3274-3830-9d2e-6897a70f6b67',family_id,product_id,catalog_item_id,sku_code,presentation,'UNSPECIFIED','UNIT',1,0,true,true,'UNSPECIFIED','ACTIVE',true,0,now(),now() FROM import_product ON CONFLICT(tenant_id,workspace_id,legacy_catalog_item_id) DO NOTHING;
DO $$ BEGIN
 IF (SELECT count(*) FROM catalog_management.product)<>102 OR (SELECT count(*) FROM catalog_management.sellable_sku)<>102 OR (SELECT count(*) FROM catalog_management.product_asset_reference)<>102 THEN RAISE EXCEPTION 'Catalog postcondition failed'; END IF;
 IF (SELECT count(*) FROM catalog_management.sku_price)<>50 OR (SELECT count(*) FROM catalog_management.product_price)<>50 THEN RAISE EXCEPTION 'Protected price rows changed'; END IF;
 IF (SELECT count(*) FROM catalog_management.product_visibility WHERE buyer_visible=false)<>52 THEN RAISE EXCEPTION 'New reference visibility policy differs'; END IF;
END $$;
SELECT 'ICISA_IMPORT_COUNTS',(SELECT count(*) FROM catalog_management.brand),(SELECT count(*) FROM catalog_management.category),(SELECT count(*) FROM catalog_management.product),(SELECT count(*) FROM catalog_management.product_asset_reference),(SELECT count(*) FROM catalog_management.product_family),(SELECT count(*) FROM catalog_management.sellable_sku),(SELECT count(*) FROM catalog_management.product_price),(SELECT count(*) FROM catalog_management.sku_price),(SELECT count(*) FROM catalog_management.product_visibility),(SELECT count(*) FROM catalog_management.seed_import_history);
COMMIT;
